using System;using System.Data;using System.Data.SqlClient;using System.IO;using System.Globalization;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Web;using System.Web.Script.Serialization;
namespace WebVault { public sealed class NoteTransferHandler:IHttpHandler {
public bool IsReusable{get{return false;}}public sealed class Input{public string action{get;set;}public string folder{get;set;}public string name{get;set;}public string data{get;set;}public string conflict{get;set;}public string version{get;set;}}
static Input Read(HttpContext c){const int limit=524288;if(c.Request.ContentLength>limit)throw new ApiFailure(413,"request_too_large");using(StreamReader r=new StreamReader(c.Request.InputStream,Encoding.UTF8)){char[] b=new char[limit+1];int n=0,k;while(n<b.Length&&(k=r.Read(b,n,b.Length-n))>0)n+=k;if(n>limit)throw new ApiFailure(413,"request_too_large");try{var j=new JavaScriptSerializer();j.MaxJsonLength=limit;Input i=j.Deserialize<Input>(new string(b,0,n));if(i==null)throw new ApiFailure(400,"invalid_json");return i;}catch(ArgumentException){throw new ApiFailure(400,"invalid_json");}catch(InvalidOperationException){throw new ApiFailure(400,"invalid_json");}}}
static bool Exists(string p){return File.Exists(p)||Directory.Exists(p);}static string Resolve(string root,string rel,bool allowRoot){if(String.IsNullOrEmpty(rel)){if(allowRoot)return root;throw new ApiFailure(400,"invalid_path");}if(rel.Length>180||rel.Split('/').Length>16||rel.IndexOf('\\')>=0)throw new ApiFailure(400,"invalid_path");string p=root;foreach(string n in rel.Split('/')){if(n.Length==0||n.Length>100||n!=n.Trim()||n.StartsWith(".")||n.EndsWith(".")||n.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(n.Split('.')[0],@"\A(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]|CONIN\$|CONOUT\$)\z",RegexOptions.IgnoreCase))throw new ApiFailure(400,"invalid_path");foreach(char ch in n)if(Char.IsControl(ch))throw new ApiFailure(400,"invalid_path");p=Path.Combine(p,n);if(Exists(p)&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new ApiFailure(409,"reparse_point_not_allowed");}p=Path.GetFullPath(p);if(p.Length>240||!p.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))throw new ApiFailure(400,"invalid_path");return p;}
static string Owned(SqlConnection db,SqlTransaction tx,ApiUser u,HttpContext c){using(SqlCommand q=new SqlCommand(@"SELECT UserId FROM auth.Users WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u AND IsActive=1 AND IsAdmin=0 AND DeletedUtc IS NULL AND MustChangePassword=0 AND EXISTS(SELECT 1 FROM auth.UserSessions WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u AND SessionId=@s AND RevokedUtc IS NULL AND ExpiresUtc>SYSUTCDATETIME() AND AbsoluteExpiresUtc>SYSUTCDATETIME())",db,tx)){q.Parameters.Add("@u",SqlDbType.Int).Value=u.UserId;q.Parameters.Add("@s",SqlDbType.BigInt).Value=u.SessionId;if(q.ExecuteScalar()==null)throw new ApiFailure(401,"unauthenticated");}using(SqlCommand q=new SqlCommand("SELECT VaultId FROM storage.UserVaults WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u",db,tx)){q.Parameters.Add("@u",SqlDbType.Int).Value=u.UserId;object v=q.ExecuteScalar();if(v==null)throw new ApiFailure(409,"vault_not_initialized");string root=Path.Combine(VaultHandler.DataRoot(c),"vaults",((Guid)v).ToString("N"));VaultHandler.PlainDirectory(root);return root;}}
static string Version(byte[] b){using(SHA256 sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLowerInvariant();}static byte[] Bytes(string p){using(FileStream f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read)){if(f.Length>262144)throw new ApiFailure(413,"note_too_large");byte[] b=new byte[(int)f.Length];int n=0,k;while(n<b.Length&&(k=f.Read(b,n,b.Length-n))>0)n+=k;if(n!=b.Length)throw new IOException("Incomplete read");return b;}}
public void ProcessRequest(HttpContext c){bool imported=false;string destination=null;try{WebApi.Prepare(c);WebApi.Post(c);ApiUser u=WebApi.RequireUser(c,true);if(u.IsAdmin)throw new ApiFailure(403,"personal_account_required");if(c.Request.Headers["X-WebVault-User"]!=u.UserId.ToString(CultureInfo.InvariantCulture))throw new ApiFailure(409,"session_changed");Input i=Read(c);if(i.action!="import"&&i.action!="export")throw new ApiFailure(400,"invalid_action");object result;using(SqlConnection db=WebApi.Open())using(SqlTransaction tx=db.BeginTransaction()){string root=Owned(db,tx,u,c);if(String.IsNullOrEmpty(i.name)||!i.name.EndsWith(".md",StringComparison.OrdinalIgnoreCase))throw new ApiFailure(400,"markdown_only");if(i.action=="export"){string p=Resolve(root,i.name,false);if(!File.Exists(p))throw new ApiFailure(404,"note_not_found");byte[] b=Bytes(p);string version=Version(b);if(i.version!=null&&!String.Equals(i.version,version,StringComparison.Ordinal))throw new ApiFailure(409,"note_changed_retry_export");result=new{ok=true,name=Path.GetFileName(p),data=Convert.ToBase64String(b),version=version};}else{if(i.name.IndexOf('/')>=0||i.name.IndexOf('\\')>=0)throw new ApiFailure(400,"filename_only");if(i.conflict!="skip"&&i.conflict!="rename")throw new ApiFailure(400,"invalid_conflict_mode");if(i.data==null||i.data.Length>349528)throw new ApiFailure(413,"note_too_large");byte[] b;try{b=Convert.FromBase64String(i.data);}catch(FormatException){throw new ApiFailure(400,"invalid_base64");}if(b.Length>262144)throw new ApiFailure(413,"note_too_large");int skip=b.Length>=3&&b[0]==239&&b[1]==187&&b[2]==191?3:0;if(new UTF8Encoding(false,true).GetString(b,skip,b.Length-skip).Length>131072)throw new ApiFailure(413,"note_too_large");string folder=i.folder??"",dir=Resolve(root,folder,true);if(!Directory.Exists(dir))throw new ApiFailure(404,"folder_not_found");VaultHandler.PlainDirectory(dir);destination=folder.Length==0?i.name:folder+"/"+i.name;string p=Resolve(root,destination,false);if(Exists(p)&&i.conflict=="skip")result=new{ok=true,skipped=true,name=destination};else{if(Exists(p)){string stem=Path.GetFileNameWithoutExtension(i.name);int suffix=1;do{if(suffix>1000)throw new ApiFailure(409,"rename_limit");string name=stem+" ("+(suffix++).ToString(CultureInfo.InvariantCulture)+").md";destination=folder.Length==0?name:folder+"/"+name;p=Resolve(root,destination,false);}while(Exists(p));}string temp=Path.Combine(dir,".wv-import-"+Guid.NewGuid().ToString("N")+".tmp");try{using(FileStream f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(b,0,b.Length);f.Flush(true);}File.Move(temp,p);imported=true;}finally{if(File.Exists(temp))File.Delete(temp);}result=new{ok=true,skipped=false,name=destination,version=Version(b)};}}tx.Commit();}WebApi.Reply(c,200,result);}catch(Exception e){if(imported){System.Diagnostics.Trace.TraceError("Import acknowledgement uncertain: {0}",e.GetType().Name);WebApi.Reply(c,503,new{ok=false,error="import_result_uncertain_refresh",name=destination});}else if(e is DecoderFallbackException)WebApi.Error(c,new ApiFailure(415,"note_must_be_utf8"));else if(e is FileNotFoundException||e is DirectoryNotFoundException)WebApi.Error(c,new ApiFailure(404,"entry_not_found"));else WebApi.Error(c,e);}}
} }
